import React, { useEffect, useState, useRef } from 'react';
import { useParams } from 'react-router-dom';
import { GoogleMap, Marker, DirectionsRenderer, useJsApiLoader } from '@react-google-maps/api';
import socket   from '../sockets/socket';
import axios    from 'axios';

export default function CustomerTrackPage() {
  const { id } = useParams<{id:string}>();
  const [drv, setDrv] = useState<{lat:number,lng:number}|null>(null);
  const [dst, setDst] = useState<{lat:number,lng:number}|null>(null);
  const [dir, setDir] = useState<google.maps.DirectionsResult|null>(null);

  useEffect(()=>{
    axios.get(`${process.env.REACT_APP_API_URL}/api/delivery/${id}`)
         .then(r=>setDst(r.data.location));
    socket.emit('trackDelivery', id!);
    socket.on('driverLocationUpdate', setDrv);
    return()=>socket.off('driverLocationUpdate',setDrv);
  },[id]);

  const { isLoaded } = useJsApiLoader({ googleMapsApiKey: process.env.REACT_APP_GOOGLE_MAPS_API_KEY! });

  useEffect(()=>{
    if(drv&&dst){
      new google.maps.DirectionsService().route({
        origin: drv, destination: dst, travelMode:'DRIVING'
      }, (r,s)=> s==='OK'&&setDir(r!));
    }
  },[drv,dst]);

  if(!isLoaded) return <div>Loading map…</div>;
  return (
    <GoogleMap
      mapContainerStyle={{width:'100%',height:'600px'}}
      center={drv||dst||{lat:6.9271,lng:79.8612}}
      zoom={14}
    >
      {drv && <Marker position={drv} label="🚚"/>}
      {dst && <Marker position={dst} label="📍"/>}
      {dir && <DirectionsRenderer directions={dir}/>}
    </GoogleMap>
  );
}
